def area(length, width):
    """Area of a rectangle."""
    return length * width

def acres(m2):
    return m2 / 4046.86

def describe(name, length, width, unit="m"):
    a = area(length, width)
    return f"{name}: {a} {unit}2 = {acres(a):.2f} acres"

print(describe("North plot", 60, 70))

