try:
    total_price(1, 10, 150)
    raise AssertionError('discount 150 should raise ValueError')
except ValueError:
    pass

exercises.solution:
def total_price(qty, unit_price, discount=0):
    if not 0 <= discount <= 100:
        raise ValueError("bad discount")
    return round(qty * unit_price * (100 - discount) / 100, 2)

